package com.fitconnect.payment.service; import com.fitconnect.payment.api.*; import com.fitconnect.payment.domain.*; import com.fitconnect.payment.repository.PaymentRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class PaymentService {private final PaymentRepository repo; public PaymentService(PaymentRepository repo){this.repo=repo;} @Transactional public PaymentResponse pay(PaymentRequest r){return PaymentResponse.from(repo.save(new Payment(r.bookingId(),r.bookingReference(),r.userId(),r.amount(),r.paymentMethod(),r.cardLastFour(),r.transactionId())));} public PaymentResponse getByBooking(Long id){return PaymentResponse.from(repo.findByBookingId(id).orElseThrow(()->new IllegalArgumentException("Paiement introuvable")));} public List<PaymentResponse> byUser(Long id){return repo.findByUserId(id).stream().map(PaymentResponse::from).toList();} @Transactional public PaymentResponse refund(Long id){Payment p=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Paiement introuvable"));p.refund();return PaymentResponse.from(repo.save(p));}}
